'use client';

import { RoomObject } from '@/data/types';

type RoomProps = {
  roomObjects: RoomObject[];
  nearId: string | null;
  collected: Set<string>;
  onInteract: (object: RoomObject) => void;
  layout: 1 | 2 | 3 | 4;
};

export default function Room({
  roomObjects,
  nearId,
  collected,
  onInteract,
  layout,
}: RoomProps) {
  const roomImages: Record<number, string> = {
    1: '/layout1-room.png',
    2: '/layout2-room.png',
    3: '/layout3-room.png',
    4: '/layout4-room.png',
  };

  return (
    <div className="relative h-full w-full overflow-hidden">

      {/* =====================================================
          ROOM BACKGROUND
          ===================================================== */}

      <img
        src={roomImages[layout]}
        alt={`Healthcare room layout ${layout}`}
        draggable={false}
        className="absolute inset-0 h-full w-full object-cover"
        style={{
          imageRendering: 'pixelated',
        }}
      />

      {/* =====================================================
          INVISIBLE INTERACTION OBJECTS
          ===================================================== */}

      {roomObjects.map((object) => {
        if (!object.interactive) {
          return null;
        }

        const isNear =
          nearId === object.id;

        return (
          <button
            key={object.id}
            type="button"
            onClick={() =>
              onInteract(object)
            }
            aria-label={`Interact with ${object.name}`}
            className={
              isNear
                ? 'absolute z-20 bg-transparent ring-2 ring-yellow-300/70'
                : 'absolute z-20 bg-transparent'
            }
            style={{
              left: `${object.x}%`,
              top: `${object.y}%`,
              width: `${object.w}%`,
              height: `${object.h}%`,
            }}
          />
        );
      })}

    </div>
  );
}