'use client';

import {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'react';

import Player from './Player';
import Room from './Room';
import ChallengeModal from './ChallengeModal';

import { challenges } from '@/data/challenges';
import { layout1Objects } from '@/data/layout1Objects';
import { layout2Objects } from '@/data/layout2Objects';
import { layout3Objects } from '@/data/layout3Objects';
import { layout4Objects } from '@/data/layout4Objects';

import {
  LayoutId,
  RoomObject,
  Direction,
} from '@/data/types';

const SPEED = 0.25;

export default function Game() {

  /*
   * =========================================================
   * GAME STATE
   * =========================================================
   */

  const [layout, setLayout] =
    useState<LayoutId>(1);

  const [pos, setPos] =
    useState({
      x: 50,
      y: 75,
    });

  const [direction, setDirection] =
    useState<Direction>('down');

  const [walking, setWalking] =
    useState(false);

  const [frame, setFrame] =
    useState(0);

  const [keys, setKeys] =
    useState<Record<string, boolean>>({});

  const [solved, setSolved] =
    useState<string[]>([]);

  const [challenge, setChallenge] =
    useState<string | null>(null);

  const [choice, setChoice] =
    useState<number | null>(null);

  const [feedback, setFeedback] =
    useState<
      'correct' | 'wrong' | null
    >(null);

  /*
   * =========================================================
   * FAKE INTERACTION
   * =========================================================
   */

  const [fakeMessage, setFakeMessage] =
    useState<string | null>(null);

  const [finished, setFinished] =
    useState(false);

  const [transitioning, setTransitioning] =
    useState(false);


  /*
   * =========================================================
   * ACTIVE CHALLENGES
   * =========================================================
   */

  const activeChallenges =
    useMemo(
      () =>
        challenges.filter(
          (challengeItem) =>
            challengeItem.layout === layout
        ),
      [layout]
    );


  /*
   * =========================================================
   * CURRENT CHALLENGE
   * =========================================================
   */

  const currentChallenge =
    challenges.find(
      (challengeItem) =>
        challengeItem.id === challenge
    ) ?? null;


  /*
   * =========================================================
   * CURRENT LAYOUT PROGRESS
   * =========================================================
   */

  const solvedInCurrentLayout =
    activeChallenges.filter(
      (challengeItem) =>
        solved.includes(
          challengeItem.id
        )
    ).length;


  /*
   * =========================================================
   * CURRENT LAYOUT COMPLETED
   * =========================================================
   */

  const currentLayoutCompleted =
    activeChallenges.length > 0 &&
    activeChallenges.every(
      (challengeItem) =>
        solved.includes(
          challengeItem.id
        )
    );


  /*
   * =========================================================
   * ROOM OBJECTS
   * =========================================================
   */

  const visibleObjects =
    useMemo(() => {

      if (layout === 1) {
        return layout1Objects;
      }

      if (layout === 2) {
        return layout2Objects;
      }

      if (layout === 3) {
        return layout3Objects;
      }

      if (layout === 4) {
        return layout4Objects.map(
          (object) => ({
            ...object,
          })
        );
      }

      return [];

    }, [layout]);


  /*
   * =========================================================
   * NEAREST INTERACTIVE OBJECT
   * =========================================================
   *
   * All objects with interactive: true can be
   * interacted with.
   *
   * Only Whiteboard and Coffee Table open
   * real challenges.
   *
   * Other interactive objects are fake interactions.
   * =========================================================
   */

  const nearObj =
    useMemo(() => {

      let nearest:
        RoomObject | null = null;

      let bestDistance = 8;

      for (
        const object of visibleObjects
      ) {

        if (!object.interactive) {
          continue;
        }

        const centerX =
          object.x +
          object.w / 2;

        const centerY =
          object.y +
          object.h / 2;

        const distance =
          Math.hypot(
            pos.x - centerX,
            pos.y - centerY
          );

        if (
          distance < bestDistance
        ) {

          bestDistance =
            distance;

          nearest =
            object;
        }

      }

      return nearest;

    }, [
      pos,
      visibleObjects,
    ]);


  /*
   * =========================================================
   * NEAREST OBJECT ID
   * =========================================================
   */

  const nearId =
    nearObj?.id ?? null;


  /*
   * =========================================================
   * GET OBJECT TYPE
   * =========================================================
   */

  const getInteractionType =
    useCallback(
      (
        object: RoomObject | null
      ) => {

        if (!object) {
          return null;
        }

        const objectText =
          `${object.id} ${object.name}`
            .toLowerCase()
            .replace(
              /[\s_-]/g,
              ''
            );

        /*
         * WHITEBOARD
         */

        if (
          objectText.includes(
            'whiteboard'
          )
        ) {

          return 'whiteboard';

        }

        /*
         * COFFEE TABLE
         */

        if (
          objectText.includes(
            'coffeetable'
          ) ||
          objectText.includes(
            'coffee'
          )
        ) {

          return 'coffee';

        }

        return null;

      },
      []
    );


  /*
   * =========================================================
   * OPEN CHALLENGE
   * =========================================================
   *
   * Whiteboard:
   * layout1-whiteboard-1 ... 5
   *
   * Coffee Table:
   * layout1-coffee-1 ... 5
   *
   * Fake interaction objects NEVER reach this
   * function from the E-key handler.
   * =========================================================
   */

  const openNextChallenge =
    useCallback(() => {

      if (!nearObj) {
        return;
      }

      const interactionType =
        getInteractionType(
          nearObj
        );


      /*
       * =====================================================
       * LAYOUT 1 WHITEBOARD
       * =====================================================
       */

      if (
        layout === 1 &&
        interactionType === 'whiteboard'
      ) {

        const next =
          activeChallenges.find(
            (challengeItem) =>
              challengeItem.id.startsWith(
                'layout1-whiteboard-'
              ) &&
              !solved.includes(
                challengeItem.id
              )
          );

        if (!next) {
          return;
        }

        setFakeMessage(null);

        setChallenge(
          next.id
        );

        setChoice(null);

        setFeedback(null);

        return;
      }


      /*
       * =====================================================
       * LAYOUT 1 COFFEE TABLE
       * =====================================================
       */

      if (
        layout === 1 &&
        interactionType === 'coffee'
      ) {

        const next =
          activeChallenges.find(
            (challengeItem) =>
              challengeItem.id.startsWith(
                'layout1-coffee-'
              ) &&
              !solved.includes(
                challengeItem.id
              )
          );

        if (!next) {
          return;
        }

        setFakeMessage(null);

        setChallenge(
          next.id
        );

        setChoice(null);

        setFeedback(null);

        return;
      }


      /*
       * =====================================================
       * OTHER LAYOUTS
       * =====================================================
       *
       * Keep the original behavior.
       */

      const next =
        activeChallenges.find(
          (challengeItem) =>
            !solved.includes(
              challengeItem.id
            )
        );

      if (!next) {
        return;
      }

      setFakeMessage(null);

      setChallenge(
        next.id
      );

      setChoice(null);

      setFeedback(null);

    }, [
      nearObj,
      layout,
      activeChallenges,
      solved,
      getInteractionType,
    ]);


  /*
   * =========================================================
   * MOVEMENT + COLLISION
   * =========================================================
   */

  const tryMove =
    useCallback(
      (
        dx: number,
        dy: number
      ) => {

        setPos(
          (current) => {

            const playerW = 2;
            const playerH = 3;

            const collides =
              (
                x: number,
                y: number
              ) => {

                for (
                  const object of visibleObjects
                ) {

                  if (!object.solid) {
                    continue;
                  }

                  const collision =
                    x + playerW / 2 >
                      object.x &&
                    x - playerW / 2 <
                      object.x + object.w &&
                    y + playerH / 2 >
                      object.y &&
                    y - playerH / 2 <
                      object.y + object.h;

                  if (collision) {
                    return true;
                  }

                }

                return false;

              };


            /*
             * HORIZONTAL
             */

            const nx =
              Math.max(
                6,
                Math.min(
                  94,
                  current.x + dx
                )
              );

            const xAllowed =
              !collides(
                nx,
                current.y
              );

            const finalX =
              xAllowed
                ? nx
                : current.x;


            /*
             * VERTICAL
             */

            const ny =
              Math.max(
                12,
                Math.min(
                  89,
                  current.y + dy
                )
              );

            const yAllowed =
              !collides(
                finalX,
                ny
              );

            const finalY =
              yAllowed
                ? ny
                : current.y;


            return {
              x: finalX,
              y: finalY,
            };

          }
        );

      },
      [visibleObjects]
    );


  /*
   * =========================================================
   * FAKE INTERACTION MESSAGES
   * =========================================================
   */

  const getFakeInteractionMessage =
    useCallback(
      (objectId: string) => {

        switch (objectId) {

          case 'l1-tv':
            return 'The television is turned off.';

          case 'l1-drawer':
            return 'The drawer is empty.';

          case 'l1-chair-left':
            return 'It is a comfortable chair.';

          case 'l1-chair-right':
            return 'It is a comfortable chair.';

          case 'l1-plant':
            return 'The plant looks healthy.';

          case 'l1-blue-board':
            return 'There is nothing useful here yet.';

          default:
            return 'There is nothing interesting here.';

        }

      },
      []
    );


  /*
   * =========================================================
   * KEYBOARD INPUT
   * =========================================================
   */

  useEffect(() => {

    const down =
      (
        event: KeyboardEvent
      ) => {

        const key =
          event.key.toLowerCase();


        /*
         * PREVENT PAGE SCROLL
         */

        if (
          key === 'arrowup' ||
          key === 'arrowdown' ||
          key === 'arrowleft' ||
          key === 'arrowright' ||
          key === ' '
        ) {

          event.preventDefault();

        }


        /*
         * SAVE KEY
         */

        setKeys(
          (value) => ({
            ...value,
            [key]: true,
          })
        );


        /*
         * ESCAPE
         */

        if (
          key === 'escape'
        ) {

          event.preventDefault();

          if (challenge) {

            setChallenge(null);

            setChoice(null);

            setFeedback(null);

          }

          /*
           * Also close fake interaction.
           */

          setFakeMessage(null);

          return;

        }


        /*
         * =====================================================
         * E — INTERACTION
         * =====================================================
         *
         * IMPORTANT:
         *
         * openNextChallenge() is ONLY called for:
         *
         * - Whiteboard
         * - Coffee Table
         *
         * Fake objects NEVER call it.
         * =====================================================
         */

        if (
          key === 'e' &&
          nearObj &&
          !challenge &&
          !transitioning
        ) {

          event.preventDefault();

          /*
           * Clear previous fake message.
           */

          setFakeMessage(null);


          /*
           * ===================================================
           * REAL CHALLENGE OBJECTS
           * ===================================================
           */

          if (
            nearObj.id ===
              'l1-whiteboard-challenge' ||
            nearObj.id ===
              'l1-table-challenge'
          ) {

            openNextChallenge();

            return;

          }


          /*
           * ===================================================
           * FAKE INTERACTION OBJECTS
           * ===================================================
           *
           * These objects DO NOT open questions.
           */

          if (
            nearObj.id === 'l1-tv' ||
            nearObj.id === 'l1-drawer' ||
            nearObj.id === 'l1-chair-left' ||
            nearObj.id === 'l1-chair-right' ||
            nearObj.id === 'l1-plant' ||
            nearObj.id === 'l1-blue-board'
          ) {

            setFakeMessage(
              getFakeInteractionMessage(
                nearObj.id
              )
            );

            return;

          }


          /*
           * ===================================================
           * FALLBACK FAKE INTERACTION
           * ===================================================
           */

          setFakeMessage(
            'There is nothing interesting here.'
          );

          return;

        }

      };


    const up =
      (
        event: KeyboardEvent
      ) => {

        const key =
          event.key.toLowerCase();

        setKeys(
          (value) => ({
            ...value,
            [key]: false,
          })
        );

      };


    window.addEventListener(
      'keydown',
      down
    );

    window.addEventListener(
      'keyup',
      up
    );


    const blur =
      () => {
        setKeys({});
      };


    window.addEventListener(
      'blur',
      blur
    );


    return () => {

      window.removeEventListener(
        'keydown',
        down
      );

      window.removeEventListener(
        'keyup',
        up
      );

      window.removeEventListener(
        'blur',
        blur
      );

    };

  }, [
    challenge,
    nearObj,
    transitioning,
    openNextChallenge,
    getFakeInteractionMessage,
  ]);


  /*
   * =========================================================
   * MOVEMENT LOOP
   * =========================================================
   */

  useEffect(() => {

    let animationFrame = 0;


    const updateMovement =
      () => {

        let dx = 0;

        let dy = 0;


        if (
          keys.w ||
          keys.arrowup
        ) {

          dy -= SPEED;

        }


        if (
          keys.s ||
          keys.arrowdown
        ) {

          dy += SPEED;

        }


        if (
          keys.a ||
          keys.arrowleft
        ) {

          dx -= SPEED;

        }


        if (
          keys.d ||
          keys.arrowright
        ) {

          dx += SPEED;

        }


        const isMoving =
          dx !== 0 ||
          dy !== 0;


        setWalking(
          isMoving
        );


        /*
         * DIRECTION
         */

        if (dx < 0) {

          setDirection(
            'left'
          );

        } else if (dx > 0) {

          setDirection(
            'right'
          );

        } else if (dy < 0) {

          setDirection(
            'up'
          );

        } else if (dy > 0) {

          setDirection(
            'down'
          );

        }


        /*
         * MOVE
         */

        if (
          isMoving &&
          !challenge &&
          !transitioning
        ) {

          tryMove(
            dx,
            dy
          );

        }


        animationFrame =
          requestAnimationFrame(
            updateMovement
          );

      };


    animationFrame =
      requestAnimationFrame(
        updateMovement
      );


    return () => {

      cancelAnimationFrame(
        animationFrame
      );

    };

  }, [
    keys,
    tryMove,
    challenge,
    transitioning,
  ]);


  /*
   * =========================================================
   * WALKING ANIMATION
   * =========================================================
   */

  useEffect(() => {

    if (!walking) {

      setFrame(0);

      return;

    }


    const timer =
      window.setInterval(
        () => {

          setFrame(
            (current) =>
              current === 0
                ? 1
                : 0
          );

        },
        150
      );


    return () => {

      window.clearInterval(
        timer
      );

    };

  }, [walking]);


  /*
   * =========================================================
   * ROOM TRANSITIONS
   * =========================================================
   */

  useEffect(() => {

    if (transitioning) {
      return;
    }


    /*
     * LAYOUT 1 → 2
     */

    if (
      layout === 1 &&
      currentLayoutCompleted &&
      pos.x < 12 &&
      pos.y > 82
    ) {

      setTransitioning(true);

      window.setTimeout(
        () => {

          setLayout(2);

          setPos({
            x: 50,
            y: 75,
          });

          setDirection(
            'up'
          );

          setChallenge(null);

          setChoice(null);

          setFeedback(null);

          setFakeMessage(null);

          setKeys({});

          setWalking(false);

          setFrame(0);

          setTransitioning(false);

        },
        700
      );

      return;

    }


    /*
     * LAYOUT 2 → 3
     */

    if (
      layout === 2 &&
      currentLayoutCompleted &&
      pos.x < 12 &&
      pos.y > 82
    ) {

      setTransitioning(true);

      window.setTimeout(
        () => {

          setLayout(3);

          setPos({
            x: 50,
            y: 82,
          });

          setDirection(
            'up'
          );

          setChallenge(null);

          setChoice(null);

          setFeedback(null);

          setFakeMessage(null);

          setKeys({});

          setWalking(false);

          setFrame(0);

          setTransitioning(false);

        },
        700
      );

      return;

    }


    /*
     * LAYOUT 3 → 4
     */

    if (
      layout === 3 &&
      currentLayoutCompleted &&
      pos.x > 42 &&
      pos.x < 58 &&
      pos.y < 18
    ) {

      setTransitioning(true);

      window.setTimeout(
        () => {

          setLayout(4);

          setPos({
            x: 19,
            y: 40,
          });

          setDirection(
            'down'
          );

          setChallenge(null);

          setChoice(null);

          setFeedback(null);

          setFakeMessage(null);

          setKeys({});

          setWalking(false);

          setFrame(0);

          setTransitioning(false);

        },
        700
      );

      return;

    }


    /*
     * LAYOUT 4 → 3
     */

    if (
      layout === 4 &&
      currentLayoutCompleted &&
      pos.x >= 12 &&
      pos.x <= 29 &&
      pos.y >= 29 &&
      pos.y <= 32
    ) {

      setTransitioning(true);

      window.setTimeout(
        () => {

          setLayout(3);

          setPos({
            x: 50,
            y: 20,
          });

          setDirection(
            'down'
          );

          setChallenge(null);

          setChoice(null);

          setFeedback(null);

          setFakeMessage(null);

          setKeys({});

          setWalking(false);

          setFrame(0);

          setTransitioning(false);

        },
        700
      );

      return;

    }

  }, [
    pos.x,
    pos.y,
    layout,
    transitioning,
    currentLayoutCompleted,
  ]);


  /*
   * =========================================================
   * FINISH GAME
   * =========================================================
   */

  useEffect(() => {

    if (
      layout === 4 &&
      currentLayoutCompleted
    ) {

      setFinished(true);

    }

  }, [
    layout,
    currentLayoutCompleted,
  ]);


  /*
   * =========================================================
   * SUBMIT CHALLENGE
   * =========================================================
   *
   * CORRECT:
   * 1. Mark current question as solved.
   * 2. Show correct feedback.
   * 3. Automatically open next question.
   *
   * WRONG:
   * Keep current question open.
   * =========================================================
   */

  const submit = () => {

    if (
      !currentChallenge ||
      choice === null
    ) {

      return;

    }


    /*
     * =======================================================
     * CORRECT ANSWER
     * =======================================================
     */

    if (
      choice === currentChallenge.answer
    ) {

      /*
       * Show correct feedback.
       */

      setFeedback(
        'correct'
      );


      /*
       * Mark this question as solved.
       */

      if (
        !solved.includes(
          currentChallenge.id
        )
      ) {

        setSolved(
          (value) => [
            ...value,
            currentChallenge.id,
          ]
        );

      }


      /*
       * Automatically open next question.
       */

      window.setTimeout(() => {

        let nextQuestion = null;


        /*
         * ===================================================
         * WHITEBOARD QUESTIONS
         * ===================================================
         */

        if (
          currentChallenge.id.startsWith(
            'layout1-whiteboard-'
          )
        ) {

          nextQuestion =
            activeChallenges.find(
              (challengeItem) =>
                challengeItem.id.startsWith(
                  'layout1-whiteboard-'
                ) &&
                challengeItem.id !==
                  currentChallenge.id &&
                !solved.includes(
                  challengeItem.id
                )
            ) ?? null;

        }


        /*
         * ===================================================
         * COFFEE TABLE QUESTIONS
         * ===================================================
         */

        else if (
          currentChallenge.id.startsWith(
            'layout1-coffee-'
          )
        ) {

          nextQuestion =
            activeChallenges.find(
              (challengeItem) =>
                challengeItem.id.startsWith(
                  'layout1-coffee-'
                ) &&
                challengeItem.id !==
                  currentChallenge.id &&
                !solved.includes(
                  challengeItem.id
                )
            ) ?? null;

        }


        /*
         * ===================================================
         * OTHER LAYOUTS
         * ===================================================
         */

        else {

          nextQuestion =
            activeChallenges.find(
              (challengeItem) =>
                !solved.includes(
                  challengeItem.id
                ) &&
                challengeItem.id !==
                  currentChallenge.id
            ) ?? null;

        }


        /*
         * ===================================================
         * NEXT QUESTION EXISTS
         * ===================================================
         */

        if (nextQuestion) {

          setChallenge(
            nextQuestion.id
          );

          setChoice(
            null
          );

          setFeedback(
            null
          );

          return;

        }


        /*
         * ===================================================
         * NO MORE QUESTIONS
         * ===================================================
         */

        setChallenge(
          null
        );

        setChoice(
          null
        );

        setFeedback(
          null
        );

      }, 700);

      return;

    }


    /*
     * =======================================================
     * WRONG ANSWER
     * =======================================================
     */

    setFeedback(
      'wrong'
    );

  };


  /*
   * =========================================================
   * FINISHED SCREEN
   * =========================================================
   */

  if (finished) {

    return (

      <main className="game-shell fixed inset-0 z-50 flex min-h-screen items-center justify-center p-6">

        <div className="panel max-w-2xl p-10 text-center">

          <div className="text-3xl font-black text-yellow-200">

            CONGRATULATIONS!

          </div>


          <div className="mt-5 text-xl font-black text-cyan-200">

            YOU HAVE COMPLETED THE HEALTHCARE ENGLISH CHALLENGE.

          </div>


          <p className="mt-5 text-sm text-slate-400">

            You explored all four layouts
            and completed all healthcare
            English challenges.

          </p>


          <button
            className="retro-btn mt-7 px-5 py-3"
            onClick={() =>
              location.reload()
            }
          >

            PLAY AGAIN

          </button>

        </div>

      </main>

    );

  }


  /*
   * =========================================================
   * MAIN GAME
   * =========================================================
   */

  return (

    <main className="game-shell fixed inset-0 z-50 flex h-screen w-screen items-center justify-center overflow-hidden">

      <div className="flex h-full w-full items-center justify-center">

        <div className="relative aspect-[4/3] h-[100vh] max-h-screen w-auto max-w-screen overflow-hidden border-4 border-[#20272e] bg-[#59606a] shadow-2xl">


          {/* =================================================
              ROOM
              ================================================= */}

          <Room
            roomObjects={
              visibleObjects
            }

            nearId={
              nearId
            }

            collected={
              new Set()
            }

            onInteract={
              (object) => {

                if (
                  object.interactive &&
                  !challenge &&
                  !transitioning
                ) {

                  /*
                   * =================================================
                   * REAL CHALLENGE OBJECT
                   * =================================================
                   */

                  if (
                    object.id ===
                      'l1-whiteboard-challenge' ||
                    object.id ===
                      'l1-table-challenge'
                  ) {

                    openNextChallenge();

                    return;

                  }


                  /*
                   * =================================================
                   * FAKE INTERACTION OBJECT
                   * =================================================
                   */

                  setFakeMessage(
                    getFakeInteractionMessage(
                      object.id
                    )
                  );

                }

              }
            }

            layout={
              layout
            }

          />


          {/* =================================================
              PLAYER
              ================================================= */}

          <Player
            x={pos.x}
            y={pos.y}
            direction={direction}
            walking={walking}
            frame={frame}
          />


          {/* =================================================
              HUD
              ================================================= */}

          <div className="absolute left-3 top-3 z-40 border-2 border-[#20272e] bg-black/75 px-3 py-2 text-[10px] font-black text-white">

            <div>
              LAYOUT {layout}
            </div>


            <div className="mt-1 text-cyan-200">

              CHALLENGES:{' '}
              {solvedInCurrentLayout}/
              {activeChallenges.length}

            </div>


            {!currentLayoutCompleted && (

              <div className="mt-1 text-yellow-200">

                COMPLETE ALL CHALLENGES

              </div>

            )}


            {currentLayoutCompleted &&
              layout < 4 && (

                <div className="mt-1 text-green-300">

                  EXIT UNLOCKED

                </div>

            )}

          </div>


          {/* =================================================
              E INTERACTION PROMPT
              ================================================= */}

          {nearObj &&
            !challenge &&
            !transitioning && (

              <div className="absolute bottom-6 left-1/2 z-50 -translate-x-1/2 border-2 border-yellow-300 bg-black/85 px-5 py-3 text-center text-xs font-black text-yellow-100">

                [E] INTERACT —{' '}
                {nearObj.name}

              </div>

          )}


          {/* =================================================
              FAKE INTERACTION MESSAGE
              ================================================= */}

          {fakeMessage &&
            !challenge &&
            !transitioning && (

              <div
                className="absolute bottom-20 left-1/2 z-[60] -translate-x-1/2 border-2 border-cyan-300 bg-black/90 px-5 py-3 text-center text-xs font-black text-cyan-100"
                onClick={() =>
                  setFakeMessage(null)
                }
              >

                {fakeMessage}

                <div className="mt-1 text-[8px] text-slate-400">

                  PRESS E TO INTERACT AGAIN

                </div>

              </div>

          )}


          {/* =================================================
              LOCKED MESSAGE
              ================================================= */}

          {(
            (layout === 1 &&
              pos.x < 12 &&
              pos.y > 82 &&
              !currentLayoutCompleted) ||

            (layout === 2 &&
              pos.x < 12 &&
              pos.y > 82 &&
              !currentLayoutCompleted) ||

            (layout === 3 &&
              pos.x > 42 &&
              pos.x < 58 &&
              pos.y < 18 &&
              !currentLayoutCompleted) ||

            (layout === 4 &&
              pos.x >= 12 &&
              pos.x <= 29 &&
              pos.y >= 29 &&
              pos.y <= 32 &&
              !currentLayoutCompleted)

          ) && (

            <div className="absolute bottom-6 left-1/2 z-50 -translate-x-1/2 border-2 border-red-400 bg-black/85 px-5 py-3 text-center text-xs font-black text-red-200">

              🔒 EXIT LOCKED

              <div className="mt-1 text-[9px] text-white">

                COMPLETE ALL CHALLENGES FIRST

              </div>

            </div>

          )}


          {/* =================================================
              ROOM TRANSITION
              ================================================= */}

          {transitioning && (

            <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/70">

              <div className="text-center">

                <div className="text-2xl font-black text-yellow-200">

                  ENTERING NEXT ROOM...

                </div>


                <div className="mt-2 text-xs text-slate-300">

                  {layout < 4
                    ? `LAYOUT ${layout + 1}`
                    : 'RETURNING'}

                </div>

              </div>

            </div>

          )}


          {/* =================================================
              CHALLENGE MODAL
              ================================================= */}

          {challenge &&
            currentChallenge && (

              <ChallengeModal

                challenge={
                  currentChallenge
                }

                index={
                  activeChallenges.findIndex(
                    (
                      challengeItem
                    ) =>
                      challengeItem.id ===
                      currentChallenge.id
                  ) + 1
                }

                total={
                  activeChallenges.length
                }

                choice={
                  choice
                }

                setChoice={
                  setChoice
                }

                onSubmit={
                  submit
                }

                feedback={
                  feedback
                }

                onClose={() => {

                  setChallenge(
                    null
                  );

                  setChoice(
                    null
                  );

                  setFeedback(
                    null
                  );

                }}

              />

            )}

        </div>

      </div>

    </main>

  );

}